import { EventEmitter } from 'node:events';

/** @typedef {{ paid: [orderId: string] }} OrderEvents */

/** @type {EventEmitter & { on<E extends keyof OrderEvents>(e: E, fn: (...args: OrderEvents[E]) => void): void; emit<E extends keyof OrderEvents>(e: E, ...args: OrderEvents[E]): boolean }} */
const orders = new EventEmitter();

orders.on('paid', (orderId) => console.log('paid', orderId));
orders.emit('paid', 'ord_123');

public sealed class OrderBus
{
    public event EventHandler<string>? Paid;

    public void MarkPaid(string orderId)
    {
        // only this class invokes
        Paid?.Invoke(this, orderId);
    }
}

// bus.Paid?.Invoke(...); // compile error if event not public invoke

const handler = (event) => {
  console.log(event.type, event.target);
};

document.addEventListener('click', handler);
// later
document.removeEventListener('click', handler);

public class Publisher
{
    public event EventHandler? Tick;
}

var pub = new Publisher();
var subscriber = new HeavyObject();
pub.Tick += subscriber.OnTick;

// subscriber still reachable via pub.Tick — memory leak until -=
pub.Tick -= subscriber.OnTick;
